import{_ as o,o as r,c as t,a2 as a}from"./chunks/framework.Cdp8-jB6.js";const h=JSON.parse('{"title":"v0.8 (mobile branch) — merge + deploy readiness","description":"","frontmatter":{},"headers":[],"relativePath":"wip/v0.8-merge-deploy-readiness.md","filePath":"wip/v0.8-merge-deploy-readiness.md"}'),i={name:"wip/v0.8-merge-deploy-readiness.md"};function s(n,e,d,l,c,p){return r(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="v0-8-mobile-branch-—-merge-deploy-readiness" tabindex="-1">v0.8 (mobile branch) — merge + deploy readiness <a class="header-anchor" href="#v0-8-mobile-branch-—-merge-deploy-readiness" aria-label="Permalink to &quot;v0.8 (mobile branch) — merge + deploy readiness&quot;">​</a></h1><p><em>Assessment as of 2026-07-10. Branch <code>mobile</code> @ <code>1c8b01b07d</code>, 52 ahead / 1 behind <code>origin/main</code>. Scope: what remains before merging <code>mobile</code> → <code>main</code> and deploying to the web servers. The mobile <strong>app</strong> (iOS/Android/TV store submission) is a separate track — see §4.</em></p><h2 id="_0-what-s-on-the-branch" tabindex="-1">0. What&#39;s on the branch <a class="header-anchor" href="#_0-what-s-on-the-branch" aria-label="Permalink to &quot;0. What&#39;s on the branch&quot;">​</a></h2><p>52 commits over 0.7.3, four bodies of work:</p><ul><li><strong>Capacitor mobile wrapper</strong> (ADR-078/079, #189–#221) — stream-heavy bundle, <code>assetUrl()</code> origin spine, iOS safe-area shim, WebGL context-loss recovery, deep-links/share/haptics, splash, Android-TV launchability.</li><li><strong>WebP image delivery</strong> (RFC-030 / ADR-080, #383) — WebP-only display ladder + <code>srcset</code>, git-LFS <code>masters/</code> store, <code>image-ladder.json</code>; 1.9 GB → 897 MB.</li><li><strong>RFC-031 a11y + TV</strong> — roving focus engine, command palette, canvas object indexes, accessibility statement (WCAG 2.1 AA), TV 10-foot layer + two-panel landscape landing + content-page widen.</li><li><strong>Deep-review + rebase-reconciliation fixes</strong> — a11y/mobile hardening, image-pipeline reconciliation (30 main-added images → masters + WebP tiers + provenance), the <code>rebuild-gallery-manifests</code> webp fix, docs consolidation.</li></ul><p>Local <code>npm run preflight</code> is green. Pushed to <code>origin/mobile</code>.</p><h2 id="_1-before-merge-to-main-—-blocking" tabindex="-1">1. Before merge to <code>main</code> — BLOCKING <a class="header-anchor" href="#_1-before-merge-to-main-—-blocking" aria-label="Permalink to &quot;1. Before merge to `main` — BLOCKING&quot;">​</a></h2><ul><li>[ ] <strong>Full CI green on the branch</strong> (<code>ci.yml</code>: typecheck → lint → test → validate-data → build). Preflight mirrors it locally (green), but confirm the actual run — no CI run has been observed on <code>mobile</code> yet.</li><li>[ ] <strong><code>docker-e2e.yml</code> green</strong> — the full Playwright suite (desktop-chromium + mobile-chromium + landscape). <strong>Preflight ≠ e2e; this is the big untested gate.</strong> Notes: <ul><li><code>a11y-keyboard.spec.ts</code> is now guarded desktop-only (<code>test.skip(project !== desktop-chromium)</code>) — was CI-red on mobile projects before that fix.</li><li><strong>TV layout changes are all behind the TV detector</strong> (<code>hover:none</code> + <code>pointer:coarse</code> + <code>min-width:1100</code> + <code>max-resolution:1.5dppx</code>) → desktop/mobile viewports don&#39;t match → <strong>no visual-baseline drift expected</strong>. Still: the landing DOM gained <code>.route-cards</code> + <code>formatDisplayVersion</code> — sanity-check the desktop/mobile landing visual snapshots.</li></ul></li><li>[ ] <strong><code>mobile-e2e.yml</code> green</strong> — Capacitor streaming e2e (<code>tests/e2e/mobile/streaming.spec.ts</code>).</li><li>[ ] <strong>Rebase onto latest <code>origin/main</code></strong> immediately before merge (1 commit behind now; per operator rule #2 — every push/merge).</li><li>[ ] <strong>CHANGELOG</strong> — populate <code>## [Unreleased]</code> with the v0.8 feature list (mobile wrapper, WebP delivery, a11y/TV). <code>release.yml</code> auto-publishes from the matching <code>## [X.Y.Z]</code> section, so this must be real before tagging.</li></ul><h2 id="_2-before-deploy-—-blocking" tabindex="-1">2. Before deploy — BLOCKING <a class="header-anchor" href="#_2-before-deploy-—-blocking" aria-label="Permalink to &quot;2. Before deploy — BLOCKING&quot;">​</a></h2><ul><li>[ ] <strong>Version bump</strong> <code>0.8.0-wip</code> → <code>0.8.0</code> (valid semver) for the release tag. (Footer label logic already renders <code>0.8-wip</code>; a real release drops <code>-wip</code>.)</li><li>[ ] <strong>Deploy order fixes the CDN skew — do it in this order:</strong><ol><li>Merge + <strong>deploy web (<code>main</code>) first</strong> (<code>deploy-prod.yml</code>) so the CDN (<code>chipi.github.io/orrery</code>) serves the <strong>WebP</strong> tree.</li><li><em>Then</em> ship/point the mobile app. The app streams display images from <code>STREAM_ORIGIN</code> (= that CDN); until main serves WebP, a released app requesting <code>NN.webp</code> 404s. This is the exact skew that surfaced on-device during development.</li></ol></li><li>[ ] <strong>git-LFS masters</strong> are <code>fetchexclude</code>d (<code>.lfsconfig</code>) — the web build uses the committed <strong>derived</strong> tree, so <code>deploy-prod</code> needs no LFS pull. Confirm the deploy job doesn&#39;t try to smudge <code>masters/</code>.</li><li>[ ] Tag + GitHub Release + deploy are <strong>three separate actions</strong> (see CLAUDE.md) — <code>git push --tags</code>, then <code>gh release create</code>, then confirm/trigger <code>deploy-prod</code>.</li></ul><h2 id="_3-deferred-—-not-blockers-documented" tabindex="-1">3. Deferred — NOT blockers (documented) <a class="header-anchor" href="#_3-deferred-—-not-blockers-documented" aria-label="Permalink to &quot;3. Deferred — NOT blockers (documented)&quot;">​</a></h2><ul><li><strong>RFC-031 S4</strong> (free-fly camera keyboard/D-pad control) — deferred; content is fully reachable via the DOM object indexes. Documented in <code>docs/accessibility.md</code> + RFC-031.</li><li><strong>ADR-080 Slice 4</strong> (&quot;auto-derive <code>validate-data</code> invariant&quot;) — TA.md&#39;s ADR-080 row still says <em>pending</em>, but the ladder-contract test + gallery-count webp gate now exist. <strong>Doc drift to reconcile</strong> (mark Slice 4 done, or scope what&#39;s still open).</li></ul><h2 id="_4-mobile-app-store-track-—-separate-from-web-merge-deploy" tabindex="-1">4. Mobile app store track — SEPARATE from web merge/deploy <a class="header-anchor" href="#_4-mobile-app-store-track-—-separate-from-web-merge-deploy" aria-label="Permalink to &quot;4. Mobile app store track — SEPARATE from web merge/deploy&quot;">​</a></h2><p>Not blockers for the web merge, but the app&#39;s own path:</p><ul><li><strong>iOS</strong> — Apple developer account approved; App Store submission (signing, TestFlight, review) is its own process.</li><li><strong>Android + Google TV</strong> — Play Console listing; leanback banner + TV listing already scaffolded.</li><li>The app ships on its own cadence once the web CDN serves WebP (§2).</li></ul><h2 id="_5-cleanup" tabindex="-1">5. Cleanup <a class="header-anchor" href="#_5-cleanup" aria-label="Permalink to &quot;5. Cleanup&quot;">​</a></h2><ul><li>[ ] Delete the <code>mobile-prerebase-backup</code> ref once the merge lands (rollback safety no longer needed).</li><li>[ ] Stop the local dev server on <code>:5388</code>.</li></ul><hr><p><strong>Bottom line:</strong> code + docs are ready and preflight-green. The gating unknowns are the <strong>CI + docker-e2e + mobile-e2e runs</strong> (never exercised on this branch — preflight doesn&#39;t cover e2e) and the <strong>deploy ordering</strong> (web-with-WebP before the app). Everything else is a bump/changelog/rebase checklist.</p>',19)])])}const m=o(i,[["render",s]]);export{h as __pageData,m as default};
